-- =====================================================================
-- Migration data prod : rattrape l'attribution phase_id sur map_record
-- pour la manche round_id=2 (S01 E3/6).
--
-- À exécuter APRÈS la migration Doctrine Version20260531120000 qui ajoute
-- la colonne phase_id et la nouvelle contrainte unique.
--
-- Effet :
--   0. Supprime les 2 lignes apparues PENDANT la demi (laps=3 guigz--) qui
--      sinon seraient incorrectement tagguées qualif par l'étape 1 — elles
--      sont réinsérées proprement avec phase=9 à l'étape 3.
--   1. Tag les lignes restantes round 2 (toutes pré-demi) comme qualif
--      (phase 7).
--   2. Restaure les temps qualif sur les 29 records qui ont été écrasés
--      par des meilleurs temps en demi.
--   3. Insère 31 lignes tagguées semi (phase 8 ou 9) avec les temps faits
--      pendant la demi — laps=3 (car la demi est en 3 tours, bug serveur
--      les écrivait en laps=5).
--
-- Idempotence : à exécuter UNE SEULE FOIS. Les INSERT échoueront si la
-- contrainte unique sur (map_uid, player_login, laps, game_mode, round_id,
-- phase_id) est déjà satisfaite.
-- =====================================================================

-- Étape 0 : supprime les lignes NEW (apparues pendant la demi) pour pas
-- qu'elles soient capturées à tort par l'UPDATE qualif de l'étape 1.
DELETE FROM map_record WHERE round_id = 2 AND map_uid = '4MIqTEa7xC5BEO92VUv27KU1yq5' AND player_login = 'guigz--' AND laps = 3 AND game_mode = 3 AND phase_id IS NULL;
DELETE FROM map_record WHERE round_id = 2 AND map_uid = '7Nj_z9XQPmfYrogHpBXSLavlPy6' AND player_login = 'guigz--' AND laps = 3 AND game_mode = 3 AND phase_id IS NULL;

-- Étape 1 : tag des lignes restantes round 2 comme qualification
UPDATE map_record SET phase_id = 7 WHERE round_id = 2 AND phase_id IS NULL;

